n = int(input())
counts = {'AI': 0, 'ML': 0, 'DL': 0, 'GenAI': 0, 'Invalid': 0}
for _ in range(n):
    name, learns, neural, generates = [part.strip() for part in input().split(',')]
    learns = learns.lower() == 'yes'
    neural = neural.lower() == 'yes'
    generates = generates.lower() == 'yes'
    if neural and not learns:
        key, label = 'Invalid', 'Invalid'
    elif not learns:
        key, label = 'AI', 'AI (rule-based)'
    elif not neural:
        key, label = 'ML', 'Machine Learning'
    elif not generates:
        key, label = 'DL', 'Deep Learning'
    else:
        key, label = 'GenAI', 'Generative AI'
    counts[key] += 1
    print(f'{name}: {label}')
print('Summary: ' + ' '.join(f'{k}={v}' for k, v in counts.items()))
